-- Arbeitsrecht Berufsbildung > Soziale gesellschaftliche Themen > Datenschutz > Vertraulichkeit schützen
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein IT-Betrieb die Vertraulichkeit von Kundendaten gemäß DSGVO schützen?', 2, '[{"text": "Ja", "correct": true, "because": "DSGVO Art. 5 fordert Vertraulichkeit"}, {"text": "Nein", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Vertraulichkeit in einem IT-Betrieb durch Verschlüsselung gewährleistet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Verschlüsselung schützt vor unbefugtem Zugriff"}, {"text": "Nein", "correct": false, "because": "Technische Maßnahme ist effektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Schutz der Vertraulichkeit in einem IT-Betrieb nur für Kundendaten relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Mitarbeiter- und andere Daten sind geschützt"}, {"text": "Ja", "correct": false, "because": "Alle personenbezogenen Daten betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Fachinformatiker bei der Arbeit mit sensiblen Daten Vertraulichkeit gewährleisten?', 2, '[{"text": "Ja", "correct": true, "because": "DSGVO gilt für alle Beschäftigten"}, {"text": "Nein", "correct": false, "because": "Pflicht für alle"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb die Vertraulichkeit ohne technische Maßnahmen schützen?', 2, '[{"text": "Nein", "correct": true, "because": "DSGVO Art. 32 fordert technische Schutzmaßnahmen"}, {"text": "Ja", "correct": false, "because": "Technische Maßnahmen sind erforderlich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt den Schutz der Vertraulichkeit in einem IT-Betrieb?', 2, '[{"text": "Datenschutz-Grundverordnung (DSGVO)", "correct": true, "because": "DSGVO Art. 5 und 32 regeln Vertraulichkeit"}, {"text": "ArbSchG", "correct": false, "because": "Regelt Arbeitsschutz"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel des Schutzes der Vertraulichkeit in einem IT-Betrieb?', 3, '[{"text": "Verhinderung unbefugten Zugriffs", "correct": true, "because": "Vertraulichkeit schützt Datenintegrität"}, {"text": "Erhöhung der Arbeitszeit", "correct": false, "because": "Kein Ziel"}, {"text": "Reduktion der Produktivität", "correct": false, "because": "Nicht beabsichtigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme schützt die Vertraulichkeit von Daten in einem IT-Betrieb?', 3, '[{"text": "Zugangskontrollen", "correct": true, "because": "Verhindert unbefugten Zugriff"}, {"text": "Öffentliche Freigabe", "correct": false, "because": "Verstößt gegen Vertraulichkeit"}, {"text": "Keine Verschlüsselung", "correct": false, "because": "Verschlüsselung ist notwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist für den Schutz der Vertraulichkeit von Daten in einem IT-Betrieb verantwortlich?', 2, '[{"text": "Der Verantwortliche (z. B. Geschäftsführer)", "correct": true, "because": "DSGVO Art. 4 legt Verantwortung fest"}, {"text": "Die Auszubildenden", "correct": false, "because": "Nicht deren Pflicht"}, {"text": "Die Kunden", "correct": false, "because": "Kunden sind Betroffene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht einem IT-Betrieb bei Verletzung der Vertraulichkeit?', 3, '[{"text": "Bußgelder", "correct": true, "because": "DSGVO sieht hohe Strafen vor"}, {"text": "Geringere Produktivität", "correct": false, "because": "Keine direkte Folge"}, {"text": "Weniger Mitarbeiter", "correct": false, "because": "Indirekte Folge"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen schützen die Vertraulichkeit in einem IT-Betrieb?', 4, '[{"text": "Verschlüsselung", "correct": true, "because": "Schützt Daten vor Zugriff"}, {"text": "Zugangskontrollen", "correct": true, "because": "Verhindert unbefugten Zugriff"}, {"text": "Öffentliche Speicherung", "correct": false, "because": "Verstößt gegen Vertraulichkeit"}, {"text": "Passwortschutz", "correct": true, "because": "Erhöht Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet der Schutz der Vertraulichkeit einem IT-Betrieb?', 3, '[{"text": "Schutz vor Datenlecks", "correct": true, "because": "Vertraulichkeit verhindert Verlust"}, {"text": "Kundenzufriedenheit", "correct": true, "because": "Vertrauen wird gestärkt"}, {"text": "Höhere Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Rechtssicherheit", "correct": true, "because": "DSGVO wird eingehalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen durch unzureichenden Schutz der Vertraulichkeit in einem IT-Betrieb?', 4, '[{"text": "Bußgelder", "correct": true, "because": "DSGVO sanktioniert Verstöße"}, {"text": "Datenlecks", "correct": true, "because": "Unbefugter Zugriff möglich"}, {"text": "Geringere Arbeitsbelastung", "correct": false, "because": "Kein Risiko"}, {"text": "Imageschaden", "correct": true, "because": "Vertrauensverlust droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesetzlichen Anforderungen regeln den Schutz der Vertraulichkeit in einem IT-Betrieb?', 3, '[{"text": "DSGVO Art. 5 (Vertraulichkeit)", "correct": true, "because": "Grundprinzip der DSGVO"}, {"text": "DSGVO Art. 32 (Sicherheitsmaßnahmen)", "correct": true, "because": "Technische Schutzmaßnahmen"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}, {"text": "DSGVO Art. 33 (Meldepflicht)", "correct": true, "because": "Relevante Folge bei Verlust"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten müssen in einem IT-Betrieb vertraulich geschützt werden?', 3, '[{"text": "Kundendaten", "correct": true, "because": "Personenbezogen gemäß DSGVO"}, {"text": "Mitarbeiterdaten", "correct": true, "because": "Ebenfalls personenbezogen"}, {"text": "Öffentliche Firmendaten", "correct": false, "because": "Nicht vertraulich"}, {"text": "Passwörter", "correct": true, "because": "Schützen Zugriff auf Daten"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die DSGVO fordert den Schutz der Vertraulichkeit in einem IT-Betrieb. b) Verschlüsselung ist keine Maßnahme dafür.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DSGVO ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Vertraulichkeit schützen bedeutet, unbefugten Zugriff zu verhindern. b) Der Arbeitgeber ist dafür verantwortlich.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Zugriffsschutz und Arbeitgeberpflicht"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zugangskontrollen schützen die Vertraulichkeit in einem IT-Betrieb. b) Vertraulichkeit gilt nur für Kundendaten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kontrollen ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Verlust der Vertraulichkeit kann Bußgelder nach sich ziehen. b) Fachinformatiker müssen die Vertraulichkeit nicht beachten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bußgelder ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Passwortschutz ist eine Maßnahme zur Sicherung der Vertraulichkeit. b) Vertraulichkeit schützen erhöht die Produktivität direkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Passwortschutz ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

